@page "/apply"
@rendermode InteractiveServer
@using sv_9f3ca9887c7142d69edd32cf291ccd84.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 1:
            <PersonalInfoStep Model="personalInfo"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="() => AdvanceStep(1)" />
            break;

        case 2:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="() => AdvanceStep(2)"
                             OnBack="() => GoToStep(1)" />
            break;

        case 3:
            <ReferencesStep References="references"
                            OnNext="() => AdvanceStep(3)"
                            OnBack="() => GoToStep(2)" />
            break;

        case 4:
            <CoverLetterStep @bind-CoverLetter="coverLetter"
                             OnNext="() => AdvanceStep(4)"
                             OnBack="() => GoToStep(3)" />
            break;

        case 5:
            <ReviewStep Personal="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="coverLetter"
                        SubmittedId="submittedId"
                        OnEditSection="GoToStep"
                        OnBack="() => GoToStep(4)"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();
    private int? submittedId;

    // Form state
    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = "";

    private void AdvanceStep(int fromStep)
    {
        completedSteps.Add(fromStep);
        currentStep = fromStep + 1;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate ?? DateTime.MinValue,
                e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        submittedId = await ApplicationService.SubmitApplicationAsync(application);
        completedSteps.Add(5);
    }
}

::deep .step-indicator {
    padding: 0 1rem;
}

::deep .step-item {
    flex: 1;
    cursor: default;
    position: relative;
}

::deep .step-item.completed {
    cursor: pointer;
}

::deep .step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
    transition: all 0.2s ease;
}

::deep .step-circle.active {
    background: #0d6efd;
    border-color: #0d6efd;
    color: #fff;
}

::deep .step-circle.completed {
    background: #198754;
    border-color: #198754;
    color: #fff;
}

::deep .step-circle.dimmed {
    opacity: 0.5;
}

::deep .step-label {
    font-size: 0.75rem;
    color: #6c757d;
}

::deep .step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

::deep .step-item.completed .step-label {
    color: #198754;
}

::deep .step-item.dimmed .step-label {
    opacity: 0.5;
}

